begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(58696574482195189478)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'PHONE_NUMBER_WITH_COUNTRY_FLAG'
,p_display_name=>'Phone Number with Country Flag'
,p_apexlang_name=>'phoneNumberWithCountryFlag'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS:APEX_APPL_PAGE_IG_COLUMNS'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#docx-preview.min.js',
'#PLUGIN_FILES#utils#MIN#.js'))
,p_css_file_urls=>'#PLUGIN_FILES#intlTelInput.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure render_phone_item (',
'    p_item   in            apex_plugin.t_page_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_render_param,',
'    p_result in out nocopy apex_plugin.t_item_render_result',
')',
'is',
'    l_name varchar2(100) := p_item.name;',
'    l_js   varchar2(32767);',
'begin',
'    -- 1. Input HTML Box Render',
'    sys.htp.p(',
'        ''<input type="tel" id="'' || p_item.name || ''" name="'' || l_name || ''" '' ||',
'        ''class="text_field apex-item-text" value="'' || apex_escape.html_attribute(p_param.value) || ''" autocomplete="tel" />''',
'    );',
'',
'    -- 2. Construct JS safely using q-quotes',
'    l_js := q''[',
'        (function() {',
'            var itemId = "]'' || p_item.name || q''[";',
'            var $item = $("#" + itemId);',
'            if (!$item.length) return;',
'',
'            var elem = $item[0];',
'            var iti = window.intlTelInput(elem, {',
'                initialCountry: "in",',
'                separateDialCode: true,',
'                nationalMode: false,',
'                autoPlaceholder: "aggressive",',
'                strictMode: true,',
'                utilsScript: "]'' || p_plugin.file_prefix || q''[utils.js"',
'            });',
'',
'            // Initial Value Setup',
'            if (elem.value) {',
'                iti.setNumber(elem.value);',
'            }',
'',
'            // Strict Country-wise Phone Validation Helper',
'            function isStrictlyValid() {',
'                if (typeof intlTelInputUtils !== "undefined") {',
'                    return iti.isValidNumber();',
'                }',
'                return iti.isValidNumber() && iti.isPossibleNumber();',
'            }',
'',
'            // Function to Show STRICTLY Inline Error Only',
'            function checkAndShowError() {',
'                var val = elem.value.trim();',
'                var countryData = iti.getSelectedCountryData();',
'                var dialCodeStr = countryData ? "+" + countryData.dialCode : "";',
'',
'                if (val === "" || val === dialCodeStr) {',
'                    apex.message.clearErrors(itemId);',
'                    return true;',
'                }',
'',
'                if (!isStrictlyValid()) {',
'                    apex.message.showErrors([',
'                        {',
'                            type: "error",',
'                            location: ["inline"],',
'                            pageItem: itemId,',
'                            message: "Please enter a valid phone number for " + (countryData ? countryData.name : "the selected country") + ".",',
'                            unsafe: false',
'                        }',
'                    ]);',
'                    return false;',
'                } else {',
'                    apex.message.clearErrors(itemId);',
'                    return true;',
'                }',
'            }',
'',
'            // APEX Item Interface Registration',
'            apex.item.create(itemId, {',
'                getValue: function() {',
'                    return iti.getNumber() || elem.value;',
'                },',
'                setValue: function(pValue) {',
'                    if (pValue) {',
'                        iti.setNumber(pValue);',
'                    } else {',
'                        elem.value = "";',
'                    }',
'                    checkAndShowError();',
'                },',
'                getValidationErrors: function() {',
'                    var val = elem.value.trim();',
'                    if (val !== "" && !isStrictlyValid()) {',
'                        return ["Please enter a valid phone number."];',
'                    }',
'                    return null;',
'                }',
'            });',
'',
'            // 1. BLOCK NON-NUMERIC KEYS (Numbers, Backspace, Delete, Arrows, Tab, + allowed)',
'            elem.addEventListener("keydown", function(e) {',
'                var allowedKeys = [',
'                    "Backspace", "Delete", "Tab", "Escape", "Enter",',
'                    "ArrowLeft", "ArrowRight", "Home", "End"',
'                ];',
'',
'                if (allowedKeys.indexOf(e.key) !== -1 ||',
'                    (e.ctrlKey === true || e.metaKey === true)',
'                ) {',
'                    return;',
'                }',
'',
'                if (!/^[0-9+]$/.test(e.key)) {',
'                    e.preventDefault();',
'                }',
'            });',
'',
'            // 2. REALTIME VALIDATION & FORMATTING ON INPUT',
'            elem.addEventListener("input", function() {',
'                elem.value = elem.value.replace(/[^0-9+]/g, "");',
'',
'                var currentNum = iti.getNumber();',
'                if (currentNum) {',
'                    var formattedNum = iti.getNumber(intlTelInputUtils.numberFormat.NATIONAL);',
'                    if (formattedNum && !elem.value.startsWith("+")) {',
'                        elem.value = formattedNum;',
'                    }',
'                }',
'                checkAndShowError();',
'            });',
'',
'            // Reset when country flags change',
'            elem.addEventListener("countrychange", function() {',
'                elem.value = "";',
'                apex.message.clearErrors(itemId);',
'                var countryData = iti.getSelectedCountryData();',
'                if (countryData && countryData.dialCode) {',
'                    elem.value = "+" + countryData.dialCode;',
'                }',
'            });',
'',
'            // Focus Out (Blur) final check',
'            elem.addEventListener("blur", function() {',
'                checkAndShowError();',
'                $item.trigger("change");',
'            });',
'        })();',
'    ]'';',
'',
'    -- 3. Add JS Code to Page',
'    apex_javascript.add_onload_code(p_code => l_js);',
'',
'end render_phone_item;'))
,p_api_version=>3
,p_render_function=>'render_phone_item'
,p_item_session_state_data_type=>'VARCHAR2'
,p_standard_attributes=>'VISIBLE:ELEMENT:WIDTH:HEIGHT:ELEMENT_OPTION:PLACEHOLDER:ICON:ENCRYPT'
,p_version_scn=>'SH256:mTahOlDewpCGmoy-IEPli1BU9f6lQz24rCjCnhP60xo'
,p_version_identifier=>'1.0'
,p_about_url=>'https://www.linkedin.com/in/jenishpatel7'
,p_files_version=>2461253063116
);
end;
